  /**
   * One of `aster_path_kind_t` (`DIRECT`, `RELAY` or `OTHER`).
   */
  uint32_t path_kind;
  /**
   * 1 if this path currently carries application data.
   */
  uint32_t is_selected;
  /**
   * DIRECT: the peer's UDP port.
   */
  uint16_t peer_port;
  uint16_t _pad;
  /**
   * DIRECT: the peer's IP address.
   */
  struct aster_bytes_t peer_host;
  /**
   * RELAY: the relay URL.
   */
